const color = (n) => `var(--c${(n - 1) % 4})`;
const pct = (n, of) => (of === 0 ? 0 : Math.round((n / of) * 100));
const plain = (text) => text.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();

const enabledIn = (state) => SESSIONS.slice(0, STATES[state].enabled);
const highlightedIn = (state) => enabledIn(state).at(-1) ?? null;

const activeKeys = (state, n) => (n === 2 && STATES[state].polls != null ? Object.keys(POLLS).filter((k) => STATES[state].polls[k] === 'active') : []);

const closedPolls = (v, state, n) => {
  if (n !== 2) {
    return CLOSED_POOL.slice(0, SESSIONS[n - 1].closed);
  }

  const keys = STATES[state].polls == null ? Object.keys(POLLS) : Object.keys(POLLS).filter((k) => STATES[state].polls[k] === 'closed');

  return keys.map((k) => ({ ...POLLS[k], mine: v.votes[k].mine ?? CLOSED_MINE[k] }));
};

/* ---------- Polls ---------- */

const withVote = (poll, mine) => {
  if (mine == null) {
    return poll;
  }

  if (poll.type === 'choice') {
    return { ...poll, options: poll.options.map(([o, n]) => [o, o === mine ? n + 1 : n]) };
  }

  if (poll.type === 'scale') {
    return { ...poll, counts: poll.counts.map((n, i) => (i === mine ? n + 1 : n)) };
  }

  const known = poll.words.map(([w, n]) => [w, mine.includes(w) ? n + 1 : n]);

  return { ...poll, words: [...known, ...mine.filter((w) => !poll.words.some(([k]) => k === w)).map((w) => [w, 1])] };
};

const answers = (poll) => poll.type === 'choice'
  ? poll.options.reduce((a, [, n]) => a + n, 0)
  : poll.type === 'scale' ? poll.counts.reduce((a, b) => a + b, 0) : poll.words.reduce((a, [, n]) => a + n, 0);

const resultsOf = (counted, mine) => {
  if (counted.type === 'choice') {
    const of = answers(counted);

    return `<div class="rows">${counted.options.map(([o, n]) => `
      <div class="row ${o === mine ? 'mine' : ''}"><i class="fill" style="width:${pct(n, of)}%"></i><span>${o === mine ? '✓ ' : ''}${o}</span><span>${pct(n, of)}%</span></div>`).join('')}</div>`;
  }

  if (counted.type === 'scale') {
    const max = Math.max(...counted.counts);

    return `<div class="scale">${counted.counts.map((n, i) => `<div><div class="bar ${i === mine ? 'mine' : ''}" style="height:${10 + (n / max) * 60}px">${n}</div><div style="text-align:center;font-size:13px">${i + 1}</div></div>`).join('')}</div>
      <div class="ends"><span>${counted.ends[0]}</span><span>${counted.ends[1]}</span></div>`;
  }

  const max = Math.max(...counted.words.map(([, n]) => n));

  return `<div class="cloud">${counted.words.map(([w, n]) => `<span style="font-size:${14 + (n / max) * 24}px; opacity:${0.55 + (n / max) * 0.45}; ${(mine ?? []).includes(w) ? 'text-decoration: underline;' : ''}">${w}</span>`).join('')}</div>`;
};

const voting = (key, poll, pv) => {
  if (poll.type === 'choice') {
    return `<div class="rows">${poll.options.map(([o]) => `<button class="row" data-poll="${key}" data-vote="${o}"><span>${o}</span></button>`).join('')}</div>`;
  }

  if (poll.type === 'scale') {
    return `<div class="scale">${[1, 2, 3, 4, 5].map((n) => `<button data-poll="${key}" data-vote="${n - 1}">${n}</button>`).join('')}</div>
      <div class="ends"><span>${poll.ends[0]}</span><span>${poll.ends[1]}</span></div>`;
  }

  return `<div class="word-in"><input data-poll="${key}" data-word placeholder="${pv.mine == null ? 'Tus palabras, separadas por coma' : 'Más palabras, separadas por coma'}" value="${pv.word}"><button class="btn small" data-poll="${key}" data-send>Enviar</button></div>
    ${pv.mine == null ? '' : `<div class="meta" style="margin-top:8px">Tus palabras: ${pv.mine.join(', ')}</div>`}`;
};

const activePanel = (v, key) => {
  const poll = POLLS[key];
  const pv = v.votes[key];
  const meta = pv.editing
    ? (poll.type === 'cloud' ? 'Sumá más palabras, separadas por coma' : `Tu voto anterior se retiró · ${answers(poll)} respuestas`)
    : `${pv.mine == null ? 'Abierta' : 'Votaste'} · ${answers(withVote(poll, pv.mine))} respuestas`;
  const edit = pv.mine == null && !pv.editing
    ? ''
    : `<div class="edit"><button class="textlink" data-poll="${key}" data-edit>${pv.editing ? 'Cancelar' : poll.type === 'cloud' ? 'Sumar más palabras' : 'Cambiar mi voto'}</button></div>`;
  const body = pv.mine != null && !pv.editing
    ? `${poll.type === 'cloud' ? `<div class="meta" style="margin-top:8px">Tus palabras: ${pv.mine.join(', ')}</div>` : ''}${resultsOf(withVote(poll, pv.mine), pv.mine)}`
    : voting(key, poll, pv);

  return `<div class="panel"><div class="q">${ic('chart-bar', 18)}<span>${poll.question}</span></div><div class="meta">${meta}</div>${body}${edit}</div>`;
};

/* ---------- Page ---------- */

const plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;

