        <div><div class="flabel">Escritorio</div><div class="desk">${app(alt, v, k)}</div></div>
      </div>
    </div>`).join('');

  // Re-rendering would jump every frame back to the top; keep where each one was.
  [...root.querySelectorAll('.scroll, .modal-body')].forEach((el, i) => {
    if (scrolls[i] != null && scrolls[i][0] === el.className) {
      el.scrollTop = scrolls[i][1];
    }
  });
};

