    const t = e.target;

    if (t.matches('[data-word]')) {
      v.votes[t.dataset.poll].word = t.value;
    } else if (t.matches('[data-draft]')) {
      v.draft = t.value;
    } else if (t.matches('[data-name]')) {
      v.editing.name = t.value;
      root.querySelectorAll('[data-name]').forEach((i) => { i.value = t.value; });
      root.querySelectorAll('[data-save]').forEach((b) => { b.disabled = v.editing.name.trim() === ''; });
    } else if (t.matches('[data-q]')) {
      v.query = t.value;
      root.querySelectorAll('[data-q]').forEach((i) => { i.value = t.value; });
      root.querySelectorAll('.agrid').forEach((g) => { g.innerHTML = avatarGrid(v); });
    }
  });

  root.addEventListener('click', (e) => {
    const v = view[alt];
    const t = e.target.closest('button, [data-toggle], [data-close], [data-keep], [data-stay]');

    if (t == null || t.disabled || (t.hasAttribute('data-stay') && !t.matches('button'))) {
      return;
    }

    const d = t.dataset;
    const state = t.closest('[data-in]')?.dataset.in ?? v.state;
    const pv = v.votes[d.poll];
    const poll = POLLS[d.poll];

    if (d.state != null) {
      Object.assign(v, { state: d.state, all: false, votes: freshVotes(), out: false });
      closeAll(v);
    } else if (t.hasAttribute('data-all')) {
      v.all = !v.all;
      closeAll(v);
    } else if (d.stripOpen != null) {
      closeAll(v);
      v.modal = { kind: d.stripOpen, n: highlightedIn(v.state).n };
    } else if (t.hasAttribute('data-strip-menu')) {
      const on = v.menu;

      closeAll(v);
      Object.assign(v, { menu: !on, out: false });
    } else if (t.hasAttribute('data-strip-profile') || t.hasAttribute('data-edit-profile')) {
      closeAll(v);
      Object.assign(v, { editing: { name: v.profile.name, avatar: v.profile.avatar }, out: false });
    } else if (t.hasAttribute('data-dark') || t.hasAttribute('data-darkmode')) {
      v.dark = !v.dark;
    } else if (t.hasAttribute('data-reset')) {
      view[alt] = fresh();
    } else if (d.toggle != null) {
      const n = Number(d.toggle);

      v.open[state] = v.open[state] === n ? null : n;
    } else if (t.hasAttribute('data-menu')) {
      v.menu = !v.menu;
    } else if (t.hasAttribute('data-logout')) {
      closeAll(v);
      v.out = true;
    } else if (t.hasAttribute('data-back')) {
      v.out = false;
    } else if (d.open != null) {
      closeAll(v);
      v.modal = { kind: d.open, n: Number(d.n) };
    } else if (t.hasAttribute('data-close')) {
      closeAll(v);
    } else if (d.acc != null) {
      v.openPoll = v.openPoll === Number(d.acc) ? null : Number(d.acc);
    } else if (d.avatar != null) {
      v.editing.avatar = d.avatar;
    } else if (t.hasAttribute('data-save')) {
      v.profile = { ...v.profile, name: v.editing.name.trim(), avatar: v.editing.avatar };
      closeAll(v);
    } else if (d.up != null) {
      const q = Object.values(v.questions).flat().find((x) => x.id === d.up);
      const on = v.upvoted.includes(q.id);

      q.votes += on ? -1 : 1;
      v.upvoted = on ? v.upvoted.filter((id) => id !== q.id) : [...v.upvoted, q.id];
    } else if (d.del != null) {
      v.confirm = d.del;
    } else if (t.hasAttribute('data-keep')) {
      v.confirm = null;
    } else if (t.hasAttribute('data-confirm-del')) {
      const n = v.confirm.split('-')[0];

      v.questions[n] = v.questions[n].filter((q) => q.id !== v.confirm);
      v.confirm = null;
    } else if (t.hasAttribute('data-ask')) {
      const n = v.modal.n;

      if (v.draft.trim() === '') {
        return;
      }

      v.questions[n] = [...v.questions[n], { id: `${n}-${Date.now()}`, text: v.draft.trim(), votes: 0, mine: true }];
      v.draft = '';
    } else if (t.hasAttribute('data-edit')) {
      // Going back to vote withdraws the previous vote (not the words of a word cloud); "Cancelar" puts it back.
      if (poll.type === 'cloud') {
        pv.editing = !pv.editing;
      } else if (pv.editing) {
        Object.assign(pv, { editing: false, mine: pv.previous, previous: null });
      } else {
        Object.assign(pv, { editing: true, previous: pv.mine, mine: null });
      }
    } else if (t.hasAttribute('data-send')) {
      const words = pv.word.split(',').map((w) => w.trim().toLowerCase()).filter((w) => w !== '');

      if (words.length === 0) {
        return;
      }

      Object.assign(pv, { mine: [...new Set([...(pv.mine ?? []), ...words])], word: '', editing: false });
    } else if (d.vote != null) {
      Object.assign(pv, { mine: poll.type === 'scale' ? Number(d.vote) : d.vote, editing: false, previous: null });
    } else {
      return;
    }

    render(alt);
  });

  render(alt);
});
</script>
</body>
</html>

